use clap::Command;
use serde::Serialize;
use standout::cli::{App, CommandContext, ExternalFailure, FnHandler, HandlerResult, Output};
use standout::EmbeddedTemplates;

#[derive(Serialize)]
struct Row {
    id: String,
    name: String,
}

const TEMPLATES: &[(&str, &str)] = &[
    ("arr", "template sees: {{ view.hello }} / data-len {{ self }}\n"),
    ("obj", "obj template: {{ items | length }} {{ view.hello }}\n"),
];

fn arr(_m: &clap::ArgMatches, _c: &CommandContext) -> HandlerResult<Vec<Row>> {
    Ok(Output::Render(vec![Row {
        id: "abc".into(),
        name: "web".into(),
    }]))
}

fn binary(_m: &clap::ArgMatches, _c: &CommandContext) -> HandlerResult<()> {
    Ok(Output::Binary {
        data: b"[{\"id\":\"x\"}]\n".to_vec(),
        filename: "out.json".into(),
    })
}

fn fail(_m: &clap::ArgMatches, _c: &CommandContext) -> HandlerResult<Vec<Row>> {
    Err(ExternalFailure::new(1, "probe: exact stderr line\n")?.into())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Command::new("probe")
        .subcommand_required(true)
        .subcommand(Command::new("arr"))
        .subcommand(Command::new("bin"))
        .subcommand(Command::new("fail"))
        .subcommand(Command::new("group").subcommand_required(true).subcommand(Command::new("ls")));

    let app = App::builder()
        .templates(EmbeddedTemplates::new(TEMPLATES, ""))
        .context_fn("view", |_ctx| {
            minijinja::Value::from_serialize(&serde_json::json!({"hello": "world"}))
        })
        .command_with("arr", FnHandler::new(arr), |cfg| cfg.template_name("arr"))?
        .command_with("bin", FnHandler::new(binary), |cfg| cfg)?
        .command_with("fail", FnHandler::new(fail), |cfg| cfg.template_name("arr"))?
        .build()?;

    app.run(cli, std::env::args());
    Ok(())
}

