//! The engine dockerlike talks to.
//!
//! This module is the CLI-free half of the application: frozen state plus the
//! queries the commands run against it. It knows nothing about clap, standout,
//! output modes or identifier truncation — those are the shell's business.

use std::fmt;

/// A container as the engine reports it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Container {
    pub id: &'static str,
    pub name: &'static str,
    pub image: &'static str,
    pub state: &'static str,
}

/// An image as the engine reports it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Image {
    pub id: &'static str,
    pub repository: &'static str,
    pub tag: &'static str,
    pub size: &'static str,
}

const CONTAINERS: &[Container] = &[
    Container {
        id: "3f1a9c2b7d4e0a11",
        name: "web",
        image: "alpine:3.19",
        state: "running",
    },
    Container {
        id: "7b2e5a8f0c13d4f2",
        name: "api",
        image: "alpine:3.19",
        state: "running",
    },
    Container {
        id: "3f8d4e6a1b90c7a3",
        name: "db",
        image: "postgres:16",
        state: "exited",
    },
    Container {
        id: "c04b17e9a2f5e8d4",
        name: "cache",
        image: "redis:7",
        state: "exited",
    },
];

const IMAGES: &[Image] = &[
    Image {
        id: "a1b2c3d4e5f60718",
        repository: "alpine",
        tag: "3.19",
        size: "7.4MB",
    },
    Image {
        id: "b9c8d7e6f5a40312",
        repository: "postgres",
        tag: "16",
        size: "431MB",
    },
    Image {
        id: "e5f4a3b2c1d09876",
        repository: "redis",
        tag: "7",
        size: "41MB",
    },
];

/// The field a `--filter` selects on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FilterKey {
    State,
    Name,
    Image,
}

impl FilterKey {
    /// The valid keys, in the order the diagnostics list them.
    pub const NAMES: [&'static str; 3] = ["state", "name", "image"];

    fn parse(key: &str) -> Option<Self> {
        match key {
            "state" => Some(Self::State),
            "name" => Some(Self::Name),
            "image" => Some(Self::Image),
            _ => None,
        }
    }

    fn of(self, container: &Container) -> &'static str {
        match self {
            Self::State => container.state,
            Self::Name => container.name,
            Self::Image => container.image,
        }
    }
}

/// One parsed `key=value` selection.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Filter {
    pub key: FilterKey,
    pub value: String,
}

impl Filter {
    fn matches(&self, container: &Container) -> bool {
        self.key.of(container) == self.value
    }
}

/// A `--filter` value naming an unknown key, or carrying no `=` at all.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InvalidFilter {
    /// The value exactly as the user typed it.
    pub spec: String,
}

impl fmt::Display for InvalidFilter {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "invalid filter: {} (valid keys: {})",
            self.spec,
            FilterKey::NAMES.join(", ")
        )
    }
}

impl std::error::Error for InvalidFilter {}

/// A reference that named no container, or more than one.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum UnresolvedReference {
    NoSuchObject {
        reference: String,
    },
    Ambiguous {
        reference: String,
        /// Every whole identifier the prefix matched, in listing order.
        matches: Vec<&'static str>,
    },
}

impl fmt::Display for UnresolvedReference {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NoSuchObject { reference } => write!(f, "no such object: {reference}"),
            Self::Ambiguous { reference, matches } => {
                write!(f, "ambiguous reference: {reference} matches {}", matches.join(", "))
            }
        }
    }
}

impl std::error::Error for UnresolvedReference {}

/// Every container, in listing order.
pub fn containers() -> &'static [Container] {
    CONTAINERS
}

/// Every image, in listing order.
pub fn images() -> &'static [Image] {
    IMAGES
}

/// Parse one `key=value` selection.
pub fn parse_filter(spec: &str) -> Result<Filter, InvalidFilter> {
    let invalid = || InvalidFilter {
        spec: spec.to_string(),
    };
    let (key, value) = spec.split_once('=').ok_or_else(invalid)?;
    let key = FilterKey::parse(key).ok_or_else(invalid)?;
    Ok(Filter {
        key,
        value: value.to_string(),
    })
}

/// The containers matching every filter, in listing order. No filters lists all
/// of them; filters that match nothing yield an empty list, which is a normal
/// answer rather than a failure.
pub fn list_containers(filters: &[Filter]) -> Vec<Container> {
    CONTAINERS
        .iter()
        .filter(|container| filters.iter().all(|filter| filter.matches(container)))
        .copied()
        .collect()
}

/// Resolve a reference — a container name, or an identifier prefix that must
/// name exactly one container.
pub fn resolve(reference: &str) -> Result<Container, UnresolvedReference> {
    if let Some(container) = CONTAINERS.iter().find(|c| c.name == reference) {
        return Ok(*container);
    }

    let matches: Vec<Container> = CONTAINERS
        .iter()
        .filter(|c| !reference.is_empty() && c.id.starts_with(reference))
        .copied()
        .collect();

    match matches.len() {
        0 => Err(UnresolvedReference::NoSuchObject {
            reference: reference.to_string(),
        }),
        1 => Ok(matches[0]),
        _ => Err(UnresolvedReference::Ambiguous {
            reference: reference.to_string(),
            matches: matches.into_iter().map(|c| c.id).collect(),
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn filters_compose_by_and() {
        let filters = vec![
            parse_filter("state=exited").unwrap(),
            parse_filter("image=redis:7").unwrap(),
        ];
        let listed = list_containers(&filters);
        assert_eq!(listed.iter().map(|c| c.name).collect::<Vec<_>>(), ["cache"]);
    }

    #[test]
    fn a_filter_matching_nothing_is_an_empty_list() {
        let filters = vec![parse_filter("state=paused").unwrap()];
        assert!(list_containers(&filters).is_empty());
    }

    #[test]
    fn an_unknown_key_and_a_missing_equals_are_both_invalid() {
        assert_eq!(
            parse_filter("status=running").unwrap_err().spec,
            "status=running"
        );
        assert_eq!(parse_filter("running").unwrap_err().spec, "running");
    }

    #[test]
    fn a_reference_is_a_name_or_a_unique_prefix() {
        assert_eq!(resolve("web").unwrap().id, "3f1a9c2b7d4e0a11");
        assert_eq!(resolve("7b2").unwrap().name, "api");
    }

    #[test]
    fn an_ambiguous_prefix_reports_every_whole_identifier() {
        assert_eq!(
            resolve("3f").unwrap_err(),
            UnresolvedReference::Ambiguous {
                reference: "3f".to_string(),
                matches: vec!["3f1a9c2b7d4e0a11", "3f8d4e6a1b90c7a3"],
            }
        );
    }

    #[test]
    fn an_unmatched_reference_is_no_such_object() {
        assert_eq!(
            resolve("nope").unwrap_err().to_string(),
            "no such object: nope"
        );
    }
}

