//! The CLI view data the handlers return.
//!
//! These are the values standout serializes in the structured output modes, so
//! their shape is the machine-readable contract: whole identifiers, and under
//! `--quiet` the identifier list itself rather than a record list.

use serde::Serialize;

use crate::engine::{Container, Image};

/// A container record: `id`, `name`, `image`, `state`, in that order.
#[derive(Clone, Copy, Debug, Serialize, PartialEq, Eq)]
pub struct ContainerRecord {
    pub id: &'static str,
    pub name: &'static str,
    pub image: &'static str,
    pub state: &'static str,
}

impl From<Container> for ContainerRecord {
    fn from(container: Container) -> Self {
        Self {
            id: container.id,
            name: container.name,
            image: container.image,
            state: container.state,
        }
    }
}

/// An image record: `id`, `repository`, `tag`, `size`, in that order.
#[derive(Clone, Copy, Debug, Serialize, PartialEq, Eq)]
pub struct ImageRecord {
    pub id: &'static str,
    pub repository: &'static str,
    pub tag: &'static str,
    pub size: &'static str,
}

impl From<Image> for ImageRecord {
    fn from(image: Image) -> Self {
        Self {
            id: image.id,
            repository: image.repository,
            tag: image.tag,
            size: image.size,
        }
    }
}

/// What a listing command lists. `--quiet` picks the variant — it decides what
/// the data *is*, before any renderer sees it — and both variants serialize as
/// a bare array, so the structured modes carry either the records or the
/// identifiers themselves.
#[derive(Clone, Debug, Serialize, PartialEq, Eq)]
#[serde(untagged)]
pub enum Listing<T> {
    /// `--quiet`: whole identifiers, nothing else.
    Identifiers(Vec<&'static str>),
    /// The full records.
    Records(Vec<T>),
}

impl<T> Listing<T> {
    /// Build the listing a command returns, given whether `--quiet` was passed.
    pub fn new<S: Copy>(
        quiet: bool,
        rows: &[S],
        identifier: fn(&S) -> &'static str,
        record: fn(S) -> T,
    ) -> Self {
        if quiet {
            Listing::Identifiers(rows.iter().map(identifier).collect())
        } else {
            Listing::Records(rows.iter().copied().map(record).collect())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quiet_serializes_as_the_identifier_array_itself() {
        let listing: Listing<ContainerRecord> =
            Listing::Identifiers(vec!["3f1a9c2b7d4e0a11", "7b2e5a8f0c13d4f2"]);
        assert_eq!(
            serde_json::to_string(&listing).unwrap(),
            r#"["3f1a9c2b7d4e0a11","7b2e5a8f0c13d4f2"]"#
        );
    }

    #[test]
    fn records_serialize_with_the_whole_identifier() {
        let listing = Listing::Records(vec![ContainerRecord::from(
            crate::engine::containers()[0],
        )]);
        assert_eq!(
            serde_json::to_string(&listing).unwrap(),
            r#"[{"id":"3f1a9c2b7d4e0a11","name":"web","image":"alpine:3.19","state":"running"}]"#
        );
    }
}

