//! The human-rendering rules: shortened identifiers and table geometry.
//!
//! Truncation and column widths are display decisions, so they must not reach
//! the serialized value a structured mode emits. They travel instead through
//! standout's render context, which templates see and the structured modes
//! bypass: a handler stages a [`TableView`] and [`provider`] hands it to the
//! template as `view`. The template still owns the layout — it pads with
//! `pad_right` the way standout's own help template does.

use std::cell::RefCell;

use serde::Serialize;
use standout_render::context::RenderContext;

/// How many characters of an identifier the human-rendered output shows.
pub const SHORT_IDENTIFIER: usize = 12;

/// An identifier as it is displayed: shortened, unless `--no-trunc`.
pub fn identifier(id: &str, no_trunc: bool) -> String {
    if no_trunc {
        id.to_string()
    } else {
        id.chars().take(SHORT_IDENTIFIER).collect()
    }
}

/// What the human-rendered modes show: either a table, or the bare identifier
/// list `--quiet` asks for.
#[derive(Clone, Debug, Default, Serialize, PartialEq, Eq)]
pub struct TableView {
    /// True when `--quiet` replaced the table with an identifier list.
    pub quiet: bool,
    /// The header row.
    pub header: Vec<&'static str>,
    /// Each column's width, measured over the header and the rendered rows.
    pub widths: Vec<usize>,
    /// The rendered cells, identifiers already shortened.
    pub rows: Vec<Vec<String>>,
    /// The identifiers `--quiet` prints, already shortened.
    pub identifiers: Vec<String>,
}

impl TableView {
    /// A table, with column widths computed over the rows actually rendered.
    pub fn table(header: Vec<&'static str>, rows: Vec<Vec<String>>) -> Self {
        let widths = header
            .iter()
            .enumerate()
            .map(|(column, cell)| {
                rows.iter()
                    .filter_map(|row| row.get(column))
                    .map(|cell| cell.chars().count())
                    .chain(std::iter::once(cell.chars().count()))
                    .max()
                    .unwrap_or(0)
            })
            .collect();
        Self {
            quiet: false,
            header,
            widths,
            rows,
            identifiers: Vec::new(),
        }
    }

    /// The identifier list `--quiet` prints: one per line, no header, no
    /// padding and no styling.
    pub fn identifiers(identifiers: Vec<String>) -> Self {
        Self {
            quiet: true,
            identifiers,
            ..Self::default()
        }
    }
}

thread_local! {
    static STAGED: RefCell<Option<TableView>> = const { RefCell::new(None) };
}

/// Stage the view the template will render. Called by a handler, read back by
/// [`provider`] one pipeline stage later.
pub fn stage(view: TableView) {
    STAGED.with(|staged| *staged.borrow_mut() = Some(view));
}

/// The `view` context variable. Structured modes skip templates, and with them
/// every injected context value, so nothing here can reach `--output=json`.
pub fn provider(_ctx: &RenderContext<'_>) -> minijinja::Value {
    STAGED.with(|staged| match staged.borrow().as_ref() {
        Some(view) => minijinja::Value::from_serialize(view),
        None => minijinja::Value::UNDEFINED,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn identifiers_shorten_unless_no_trunc() {
        assert_eq!(identifier("3f1a9c2b7d4e0a11", false), "3f1a9c2b7d4e");
        assert_eq!(identifier("3f1a9c2b7d4e0a11", true), "3f1a9c2b7d4e0a11");
    }

    #[test]
    fn widths_are_measured_over_the_header_and_the_rendered_rows() {
        let view = TableView::table(
            vec!["CONTAINER ID", "NAME", "IMAGE", "STATE"],
            vec![vec![
                "3f1a9c2b7d4e".to_string(),
                "web".to_string(),
                "alpine:3.19".to_string(),
                "running".to_string(),
            ]],
        );
        assert_eq!(view.widths, [12, 4, 11, 7]);
    }

    #[test]
    fn filtering_everything_out_leaves_the_header_widths() {
        let view = TableView::table(vec!["CONTAINER ID", "NAME", "IMAGE", "STATE"], vec![]);
        assert_eq!(view.widths, [12, 4, 5, 5]);
    }
}

