//! `dockerlike` — a container-engine client in the docker mold.
//!
//! One subject is reachable under two spellings: a legacy top-level verb
//! (`ps`, `images`, `inspect`) and a management-command path (`container ls`,
//! `image ls`, `container inspect`). Both spellings register the same handler,
//! so they are the same command down to their errors; only the usage line in
//! `--help` names the path that was invoked.

mod display;
mod engine;
mod handlers;
mod view;

use clap::{Arg, ArgAction, Command};
use standout::cli::{App, CommandConfig};
use standout::dispatch::{Hooks, RenderedOutput};
use standout::{embed_styles, embed_templates};

fn quiet() -> Arg {
    Arg::new("quiet")
        .short('q')
        .long("quiet")
        .action(ArgAction::SetTrue)
        .help("Only display identifiers")
}

fn no_trunc() -> Arg {
    Arg::new("no-trunc")
        .long("no-trunc")
        .action(ArgAction::SetTrue)
        .help("Don't truncate identifiers")
}

/// `ps` and `container ls`: the same command under two names.
fn container_ls(name: &'static str) -> Command {
    Command::new(name)
        .about("List containers")
        .arg(quiet())
        .arg(no_trunc())
        .arg(
            Arg::new("filter")
                .long("filter")
                .value_name("KEY=VALUE")
                .action(ArgAction::Append)
                .help("Filter containers by state, name or image"),
        )
}

/// `images` and `image ls`.
fn image_ls(name: &'static str) -> Command {
    Command::new(name)
        .about("List images")
        .arg(quiet())
        .arg(no_trunc())
}

/// `inspect` and `container inspect`.
fn container_inspect(name: &'static str) -> Command {
    Command::new(name)
        .about("Return low-level information on containers, as JSON")
        .arg(
            Arg::new("reference")
                .value_name("REF")
                .num_args(1..)
                .required(true)
                .help("A container name or identifier prefix"),
        )
}

fn cli() -> Command {
    Command::new("dockerlike")
        .about("A container-engine client in the docker mold")
        .subcommand_required(true)
        .subcommand(container_ls("ps"))
        .subcommand(image_ls("images"))
        .subcommand(container_inspect("inspect"))
        .subcommand(
            Command::new("container")
                .about("Manage containers")
                .subcommand_required(true)
                .subcommand(container_ls("ls"))
                .subcommand(container_inspect("inspect")),
        )
        .subcommand(
            Command::new("image")
                .about("Manage images")
                .subcommand_required(true)
                .subcommand(image_ls("ls")),
        )
}

/// A listing renders through one template, and prints nothing at all when
/// `--quiet` selected no identifiers: the empty page becomes no page.
fn listing(config: CommandConfig) -> CommandConfig {
    config
        .template_name("listing")
        .post_output(|_matches, _ctx, output| match output {
            RenderedOutput::Text(text) if text.formatted.is_empty() => Ok(RenderedOutput::Silent),
            other => Ok(other),
        })
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::builder()
        .version(env!("CARGO_PKG_VERSION"))
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .context_fn("view", display::provider)
        .command_with("ps", handlers::container_ls_Handler, listing)?
        .command_with("container.ls", handlers::container_ls_Handler, listing)?
        .command_with("images", handlers::image_ls_Handler, listing)?
        .command_with("image.ls", handlers::image_ls_Handler, listing)?
        .command_with("inspect", handlers::container_inspect_Handler, |config| {
            config.binary()
        })?
        .command_with(
            "container.inspect",
            handlers::container_inspect_Handler,
            |config| config.binary(),
        )?
        .build()?;

    app.verify_command(&cli())?;
    app.run(cli(), std::env::args());
    Ok(())
}

