use clap::Command;
use serde::Serialize;
use standout::cli::{App, CommandContext, FnHandler, HandlerResult, Output};
use standout::dispatch::{Hooks, RenderedOutput};
use standout::EmbeddedTemplates;
use standout_render::context::RenderContext;

#[derive(Serialize)]
struct Row {
    id: String,
    name: String,
}

const TABLE: &str = r#"{%- set widths = [] -%}
{%- for i in range(view.header | length) -%}
{%- set column = [view.header[i]] + (view.rows | map(attribute=i) | list) -%}
{%- set widths = widths + [column | map("length") | max] -%}
{%- endfor -%}
{%- set last = (view.header | length) - 1 -%}
[header]{% for h in view.header %}{% if loop.index0 == last %}{{ h }}{% else %}{{ h | col(widths[loop.index0]) }} {% endif %}{% endfor %}[/header]
{% for r in view.rows %}{% for c in r %}{% if loop.index0 == last %}{{ c }}{% else %}{{ c | col(widths[loop.index0]) }} {% endif %}{% endfor %}
{% endfor %}"#;

const TEMPLATES: &[(&str, &str)] = &[("table", TABLE), ("empty", "")];

fn table(_m: &clap::ArgMatches, _c: &CommandContext) -> HandlerResult<Vec<Row>> {
    Ok(Output::Render(vec![Row {
        id: "abc".into(),
        name: "web".into(),
    }]))
}

fn empty(_m: &clap::ArgMatches, _c: &CommandContext) -> HandlerResult<Vec<String>> {
    Ok(Output::Render(vec![]))
}

fn provider(_ctx: &RenderContext<'_>) -> minijinja::Value {
    let _ = _ctx.zzz;
    minijinja::Value::from_serialize(&serde_json::json!({
        "header": ["CONTAINER ID", "NAME", "IMAGE", "STATE"],
        "rows": [
            ["3f1a9c2b7d4e", "web", "alpine:3.19", "running"],
            ["c04b17e9a2f5", "cache", "redis:7", "exited"],
        ],
    }))
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Command::new("probe")
        .subcommand_required(true)
        .subcommand(Command::new("table"))
        .subcommand(Command::new("empty"));

    let app = App::builder()
        .templates(EmbeddedTemplates::new(TEMPLATES, ""))
        .context_fn("view", provider)
        .command_with("table", FnHandler::new(table), |cfg| {
            cfg.template_name("table")
        })?
        .command_with("empty", FnHandler::new(empty), |cfg| {
            cfg.template_name("empty")
        })?
        .hooks(
            "empty",
            Hooks::new().post_output(|_m, _c, out| match out {
                RenderedOutput::Text(t) if t.formatted.is_empty() => Ok(RenderedOutput::Silent),
                other => Ok(other),
            }),
        )
        .build()?;

    app.run(cli, std::env::args());
    Ok(())
}

