mod engine;
mod handlers;
mod view;

use clap::{Arg, ArgAction, Command};
use standout::cli::{App, CommandConfig};
use standout::dispatch::RenderedOutput;
use standout::{embed_styles, embed_templates};

fn quiet() -> Arg {
    Arg::new("quiet")
        .short('q')
        .long("quiet")
        .action(ArgAction::SetTrue)
        .help("Only display identifiers")
}

fn no_trunc() -> Arg {
    Arg::new("no-trunc")
        .long("no-trunc")
        .action(ArgAction::SetTrue)
        .help("Don't truncate identifiers")
}

/// A command spelled at `path`, e.g. `ps` or `container ls`. The two spellings
/// of one command are identical but for the usage line, which is what
/// `bin_name` fixes: it is the one thing in `--help` that names the path the
/// user actually typed.
fn spelling(path: &'static str) -> Command {
    let name = path.rsplit(' ').next().expect("a path names a command");
    Command::new(name).bin_name(format!("dockerlike {path}"))
}

/// `ps` and `container ls`: the same command under two names.
fn container_ls(path: &'static str) -> Command {
    spelling(path)
        .about("List containers")
        .arg(quiet())
        .arg(no_trunc())
        .arg(
            Arg::new("filter")
                .long("filter")
                .value_name("KEY=VALUE")
                .action(ArgAction::Append)
                .help("Filter containers by state, name or image"),
        )
}

/// `images` and `image ls`.
fn image_ls(path: &'static str) -> Command {
    spelling(path)
        .about("List images")
        .arg(quiet())
        .arg(no_trunc())
}

