//! Pipeline tests: argv in, rendered page out, through the same dispatch the
//! binary runs. The statuses and the stream split are settled by the real
//! binary instead, with `run_process`.

use dockerlike::cli::{app, command};
use standout::OutputMode;
use standout_test::{serial, TestHarness};

// The rendered page, as the harness reports it: the framework's own final
// newline is added by the process write, which the `run_process` tests below
// assert separately.
const PS_TABLE: &str = "\
CONTAINER ID NAME  IMAGE       STATE
3f1a9c2b7d4e web   alpine:3.19 running
7b2e5a8f0c13 api   alpine:3.19 running
3f8d4e6a1b90 db    postgres:16 exited
c04b17e9a2f5 cache redis:7     exited";

const PS_TABLE_WHOLE: &str = "\
CONTAINER ID     NAME  IMAGE       STATE
3f1a9c2b7d4e0a11 web   alpine:3.19 running
7b2e5a8f0c13d4f2 api   alpine:3.19 running
3f8d4e6a1b90c7a3 db    postgres:16 exited
c04b17e9a2f5e8d4 cache redis:7     exited";

const IMAGES_TABLE: &str = "\
IMAGE ID     REPOSITORY TAG  SIZE
a1b2c3d4e5f6 alpine     3.19 7.4MB
b9c8d7e6f5a4 postgres   16   431MB
e5f4a3b2c1d0 redis      7    41MB";

const QUIET: &str = "\
3f1a9c2b7d4e
7b2e5a8f0c13
3f8d4e6a1b90
c04b17e9a2f5";

const INSPECT_WEB: &str =
    "[{\"id\":\"3f1a9c2b7d4e0a11\",\"name\":\"web\",\"image\":\"alpine:3.19\",\"state\":\"running\"}]\n";

fn run(args: &[&str]) -> standout_test::TestResult {
    TestHarness::new().text_output().run(&app().unwrap(), command(), args)
}

// --- the tables ---------------------------------------------------------

#[test]
#[serial]
fn ps_lists_containers() {
    run(&["dockerlike", "ps"]).assert_stdout_eq(PS_TABLE);
}

#[test]
#[serial]
fn images_lists_images() {
    run(&["dockerlike", "images"]).assert_stdout_eq(IMAGES_TABLE);
}

#[test]
#[serial]
fn no_trunc_widens_the_identifier_column() {
    run(&["dockerlike", "ps", "--no-trunc"]).assert_stdout_eq(PS_TABLE_WHOLE);
}

#[test]
#[serial]
fn filtering_recomputes_the_column_widths() {
    run(&["dockerlike", "ps", "--filter", "image=alpine:3.19"]).assert_stdout_eq(
        "\
CONTAINER ID NAME IMAGE       STATE
3f1a9c2b7d4e web  alpine:3.19 running
7b2e5a8f0c13 api  alpine:3.19 running
",
    );
}

#[test]
#[serial]
fn filters_are_anded() {
    run(&[
        "dockerlike",
        "ps",
        "--filter",
        "state=exited",
        "--filter",
        "image=redis:7",
    ])
    .assert_stdout_eq(
        "\
CONTAINER ID NAME  IMAGE   STATE
c04b17e9a2f5 cache redis:7 exited
",
    );
}

#[test]
#[serial]
fn a_filter_matching_nothing_is_the_header_alone() {
    let result = run(&["dockerlike", "ps", "--filter", "state=paused"]);
    result.assert_success();
    result.assert_stdout_eq("CONTAINER ID NAME IMAGE STATE\n");
}

// --- an alias and its management path are one command -------------------

#[test]
#[serial]
fn the_two_spellings_render_the_same_page() {
    for (alias, path) in [
        (vec!["dockerlike", "ps"], vec!["dockerlike", "container", "ls"]),
        (
            vec!["dockerlike", "ps", "-q", "--no-trunc"],
            vec!["dockerlike", "container", "ls", "-q", "--no-trunc"],
        ),
        (
            vec!["dockerlike", "images"],
            vec!["dockerlike", "image", "ls"],
        ),
    ] {
        assert_eq!(
            run(&alias).stdout(),
            run(&path).stdout(),
            "{alias:?} and {path:?} are the same command"
        );
    }
}

#[test]
#[serial]
fn help_differs_only_in_the_usage_line() {
