        .stdout()
        .to_string();

    assert!(alias.contains("dockerlike ps [OPTIONS]"));
    assert!(path.contains("dockerlike container ls [OPTIONS]"));

    let strip = |page: &str| -> String {
        page.lines()
            .filter(|line| !line.contains("dockerlike"))
            .collect::<Vec<_>>()
            .join("\n")
    };
    assert_eq!(strip(&alias), strip(&path));
}

// --- quiet decides what the data is -------------------------------------

#[test]
#[serial]
fn quiet_prints_bare_identifiers() {
    run(&["dockerlike", "ps", "--quiet"]).assert_stdout_eq(QUIET);
}

#[test]
#[serial]
fn quiet_and_no_trunc_print_whole_identifiers() {
    run(&["dockerlike", "ps", "-q", "--no-trunc"]).assert_stdout_eq(
        "\
3f1a9c2b7d4e0a11
7b2e5a8f0c13d4f2
3f8d4e6a1b90c7a3
c04b17e9a2f5e8d4
",
    );
}

