#[serial]
fn quiet_is_never_styled_even_with_color_forced() {
    let result = TestHarness::new()
        .with_color()
        .output_mode(OutputMode::Term)
        .run(&app().unwrap(), command(), ["dockerlike", "ps", "-q"]);

    assert!(
        !result.stdout().contains('\u{1b}'),
        "quiet output carries no styling: {:?}",
        result.stdout()
    );
    result.assert_stdout_eq(QUIET);
}

#[test]
#[serial]
fn the_table_is_styled_when_color_is_forced() {
    let result = TestHarness::new()
        .with_color()
        .output_mode(OutputMode::Term)
        .run(&app().unwrap(), command(), ["dockerlike", "ps"]);

    assert!(result.stdout().contains('\u{1b}'), "the header is styled");
    assert_eq!(result.stdout_plain(), PS_TABLE);
}

#[test]
#[serial]
fn quiet_matching_nothing_prints_nothing_at_all() {
    let result = run(&["dockerlike", "ps", "--filter", "state=paused", "-q"]);
    result.assert_success();
    result.assert_stdout_eq("");
}

// --- structured output --------------------------------------------------

#[test]
#[serial]
fn structured_output_carries_the_whole_identifier() {
    for args in [
        vec!["dockerlike", "ps"],
        vec!["dockerlike", "ps", "--no-trunc"],
    ] {
        let result = TestHarness::new()
            .output_mode(OutputMode::Json)
            .run(&app().unwrap(), command(), args);
        let value: serde_json::Value = serde_json::from_str(result.stdout()).unwrap();

        assert_eq!(value.as_array().unwrap().len(), 4);
        assert_eq!(value[0]["id"], "3f1a9c2b7d4e0a11");
        assert_eq!(value[0]["name"], "web");
        assert_eq!(value[0]["image"], "alpine:3.19");
        assert_eq!(value[0]["state"], "running");
    }
}

#[test]
#[serial]
fn quiet_serializes_the_identifier_array_itself() {
    let result = TestHarness::new()
        .output_mode(OutputMode::Json)
        .run(&app().unwrap(), command(), ["dockerlike", "ps", "-q"]);
    let value: serde_json::Value = serde_json::from_str(result.stdout()).unwrap();

    assert_eq!(
        value,
        serde_json::json!([
            "3f1a9c2b7d4e0a11",
            "7b2e5a8f0c13d4f2",
            "3f8d4e6a1b90c7a3",
            "c04b17e9a2f5e8d4"
        ])
    );
}

#[test]
#[serial]
fn images_serialize_their_size() {
    let result = TestHarness::new()
        .output_mode(OutputMode::Json)
        .run(&app().unwrap(), command(), ["dockerlike", "images"]);
    let value: serde_json::Value = serde_json::from_str(result.stdout()).unwrap();

    assert_eq!(value[0]["id"], "a1b2c3d4e5f60718");
    assert_eq!(value[0]["repository"], "alpine");
    assert_eq!(value[0]["tag"], "3.19");
    assert_eq!(value[0]["size"], "7.4MB");
}

// --- inspect: the same bytes in every mode ------------------------------

#[test]
#[serial]
fn inspect_writes_the_same_json_in_every_output_mode() {
    for mode in [
        OutputMode::Auto,
        OutputMode::Text,
        OutputMode::Term,
        OutputMode::Json,
        OutputMode::Yaml,
    ] {
        let result = TestHarness::new()
            .with_color()
            .output_mode(mode)
            .run(&app().unwrap(), command(), ["dockerlike", "inspect", "web"]);

        let (bytes, _) = result.binary().expect("inspect writes bytes");
        assert_eq!(
            String::from_utf8_lossy(bytes),
            INSPECT_WEB,
            "output mode {mode:?}"
        );
    }
}

#[test]
#[serial]
fn inspect_resolves_names_and_prefixes_in_the_order_given() {
    let result = run(&["dockerlike", "container", "inspect", "7b2", "web"]);
    let (bytes, _) = result.binary().expect("inspect writes bytes");
    assert_eq!(
        String::from_utf8_lossy(bytes),
        "[{\"id\":\"7b2e5a8f0c13d4f2\",\"name\":\"api\",\"image\":\"alpine:3.19\",\"state\":\"running\"},\
         {\"id\":\"3f1a9c2b7d4e0a11\",\"name\":\"web\",\"image\":\"alpine:3.19\",\"state\":\"running\"}]\n"
    );
}

// --- rendering health ---------------------------------------------------

#[test]
#[serial]
fn every_style_tag_the_listing_renders_is_defined_by_the_theme() {
    let page = TestHarness::new()
        .with_color()
        .output_mode(OutputMode::Term)
        .run(&app().unwrap(), command(), ["dockerlike", "ps"]);

    standout_test::invariants::assert_every_tag_resolved(&page);
}

// --- statuses and streams, from the real binary -------------------------

fn process(args: &[&str]) -> standout_test::ProcessResult {
    TestHarness::new().run_process(env!("CARGO_BIN_EXE_dockerlike"), args)
}

#[test]
fn a_listing_that_matched_nothing_still_succeeds() {
    let result = process(&["ps", "--filter", "state=paused"]);
    result.assert_exit_code(0);
    assert_eq!(result.stderr(), "");
}

#[test]
fn a_rejected_filter_value_is_a_domain_error() {
    for (spec, message) in [
        (
            "status=running",
            "dockerlike: invalid filter: status=running (valid keys: state, name, image)\n",
        ),
        (
            "running",
            "dockerlike: invalid filter: running (valid keys: state, name, image)\n",
        ),
    ] {
        let result = process(&["ps", "--filter", spec]);
        result.assert_exit_code(1);
        result.assert_stdout_empty();
        assert_eq!(result.stderr(), message);
    }
}

#[test]
fn an_unresolvable_reference_is_a_domain_error() {
    let ambiguous = process(&["inspect", "3f"]);
    ambiguous.assert_exit_code(1);
    ambiguous.assert_stdout_empty();
    assert_eq!(
        ambiguous.stderr(),
        "dockerlike: ambiguous reference: 3f matches 3f1a9c2b7d4e0a11, 3f8d4e6a1b90c7a3\n"
    );

    let missing = process(&["container", "inspect", "nope"]);
    missing.assert_exit_code(1);
    missing.assert_stdout_empty();
    assert_eq!(missing.stderr(), "dockerlike: no such object: nope\n");
}

#[test]
fn usage_errors_write_guidance_to_stderr_and_nothing_to_stdout() {
    for args in [
        vec![],
        vec!["container"],
        vec!["image"],
        vec!["bogus"],
        vec!["ps", "--bogus"],
        vec!["images", "--filter", "state=running"],
        vec!["inspect"],
    ] {
        let result = process(&args);
        result.assert_exit_code(2);
        result.assert_stdout_empty();
        assert!(!result.stderr().is_empty(), "{args:?} explains itself");
    }
}

#[test]
fn help_is_a_success_on_stdout_at_every_level() {
    for args in [
        vec!["--help"],
        vec!["ps", "--help"],
        vec!["container", "--help"],
        vec!["container", "ls", "--help"],
        vec!["container", "inspect", "--help"],
        vec!["image", "ls", "--help"],
    ] {
        let result = process(&args);
        result.assert_exit_code(0);
        assert!(!result.stdout().is_empty(), "{args:?} prints help");
    }
}

#[test]
fn the_two_spellings_fail_identically() {
    for (alias, path) in [
        (vec!["ps", "--filter", "nope"], vec!["container", "ls", "--filter", "nope"]),
        (vec!["inspect", "zz"], vec!["container", "inspect", "zz"]),
    ] {
        let alias = process(&alias);
        let path = process(&path);
        assert_eq!(alias.code(), path.code());
        assert_eq!(alias.stderr(), path.stderr());
        assert_eq!(alias.stdout(), path.stdout());
    }
}

#[test]
fn inspect_writes_its_bytes_to_stdout() {
    let result = process(&["inspect", "web"]);
    result.assert_exit_code(0);
    assert_eq!(result.stdout(), INSPECT_WEB);
    assert_eq!(result.stderr(), "");
}

