//! The CLI adapters.
//!
//! Each handler translates parsed arguments, calls [`crate::engine`], stages
//! what the human-rendered modes should show, and returns the serializable
//! value. Every one of them is registered under two paths — a legacy verb and
//! a management-command path — so the two spellings are the same command.

use anyhow::Error;
use standout::cli::{ExternalFailure, Output};
use standout::handler;

use crate::display::{self, TableView};
use crate::engine::{self, Container, Image};
use crate::view::{ContainerRecord, ImageRecord, Listing};

/// A domain failure: the flag parsed, its value was rejected. These own their
/// exit status (1) and their exact stderr bytes, so they travel as an
/// `ExternalFailure` rather than picking up the framework's `Error:` framing.
fn domain_error(error: impl std::fmt::Display) -> Error {
    ExternalFailure::new(1, format!("dockerlike: {error}\n"))
        .expect("1 is a nonzero status")
        .into()
}

