//! The CLI adapters.
//!
//! Each handler translates parsed arguments, calls [`crate::engine`], stages
//! what the human-rendered modes should show, and returns the serializable
//! value. Every one of them is registered under two paths — a legacy verb and
//! a management-command path — so the two spellings are the same command.

use anyhow::Error;
use standout::cli::{ExternalFailure, Output};
use standout::handler;

use crate::display::{self, TableView};
use crate::engine::{self, Container, Image};
use crate::view::{ContainerRecord, ImageRecord, Listing};

/// A domain failure: the flag parsed, its value was rejected. These own their
/// exit status (1) and their exact stderr bytes, so they travel as an
/// `ExternalFailure` rather than picking up the framework's `Error:` framing.
fn domain_error(error: impl std::fmt::Display) -> Error {
    ExternalFailure::new(1, format!("dockerlike: {error}\n"))
        .expect("1 is a nonzero status")
        .into()
}

/// `dockerlike ps`, `dockerlike container ls`.
#[handler]
pub fn container_ls(
    #[flag] quiet: bool,
    #[flag] no_trunc: bool,
    #[arg] filter: Vec<String>,
) -> Result<Output<Listing<ContainerRecord>>, Error> {
    let mut filters = Vec::with_capacity(filter.len());
    for spec in &filter {
        filters.push(engine::parse_filter(spec).map_err(domain_error)?);
    }
    let containers = engine::list_containers(&filters);

    display::stage(if quiet {
        TableView::identifiers(
            containers
                .iter()
                .map(|container| display::identifier(container.id, no_trunc))
                .collect(),
        )
    } else {
        TableView::table(
            vec!["CONTAINER ID", "NAME", "IMAGE", "STATE"],
            containers
                .iter()
                .map(|container| {
                    vec![
                        display::identifier(container.id, no_trunc),
                        container.name.to_string(),
                        container.image.to_string(),
                        container.state.to_string(),
                    ]
                })
                .collect(),
        )
    });

    Ok(Output::Render(Listing::new(
        quiet,
        &containers,
        |container: &Container| container.id,
        ContainerRecord::from,
    )))
}

/// `dockerlike images`, `dockerlike image ls`.
#[handler]
pub fn image_ls(
    #[flag] quiet: bool,
    #[flag] no_trunc: bool,
) -> Result<Output<Listing<ImageRecord>>, Error> {
    let images = engine::images();

    display::stage(if quiet {
        TableView::identifiers(
            images
                .iter()
                .map(|image| display::identifier(image.id, no_trunc))
                .collect(),
        )
    } else {
        TableView::table(
            vec!["IMAGE ID", "REPOSITORY", "TAG", "SIZE"],
            images
                .iter()
                .map(|image| {
                    vec![
                        display::identifier(image.id, no_trunc),
                        image.repository.to_string(),
                        image.tag.to_string(),
                        image.size.to_string(),
                    ]
                })
                .collect(),
        )
    });

    Ok(Output::Render(Listing::new(
        quiet,
        images,
        |image: &Image| image.id,
        ImageRecord::from,
    )))
}

/// `dockerlike inspect`, `dockerlike container inspect`.
///
/// The machine-only command: the same JSON bytes on stdout in every output
/// mode, never styled and never framed with prose. Returning them as bytes is
/// what takes them past the render pipeline — the framework still owns the
/// write.
#[handler]
pub fn container_inspect(#[arg] reference: Vec<String>) -> Result<Output<()>, Error> {
    let mut records = Vec::with_capacity(reference.len());
    for reference in &reference {
        records.push(ContainerRecord::from(
            engine::resolve(reference).map_err(domain_error)?,
        ));
    }

    let mut json = serde_json::to_string(&records)?;
    json.push('\n');

    Ok(Output::Binary {
        data: json.into_bytes(),
        filename: "inspect.json".to_string(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rendered<T>(output: Output<T>) -> T
    where
        T: serde::Serialize,
    {
        match output {
            Output::Render(value) => value,
            _ => panic!("expected rendered data"),
        }
    }

    #[test]
    fn quiet_returns_the_identifiers_themselves_whole() {
        let listing = rendered(container_ls(true, false, vec![]).unwrap());
        assert_eq!(
            listing,
            Listing::Identifiers(vec![
                "3f1a9c2b7d4e0a11",
                "7b2e5a8f0c13d4f2",
                "3f8d4e6a1b90c7a3",
                "c04b17e9a2f5e8d4",
            ])
        );
    }

    #[test]
    fn filters_are_anded() {
        let listing = rendered(
            container_ls(
                false,
                false,
                vec!["state=exited".into(), "image=redis:7".into()],
            )
            .unwrap(),
        );
        assert_eq!(
            listing,
            Listing::Records(vec![ContainerRecord::from(engine::containers()[3])])
        );
    }

    #[test]
    fn an_invalid_filter_is_a_domain_error() {
        let error = container_ls(false, false, vec!["status=running".into()]).unwrap_err();
        assert!(error
            .to_string()
            .contains("invalid filter: status=running (valid keys: state, name, image)"));
    }

    #[test]
    fn no_trunc_does_not_change_the_returned_value() {
        let truncated = rendered(container_ls(false, false, vec![]).unwrap());
        let whole = rendered(container_ls(false, true, vec![]).unwrap());
        assert_eq!(truncated, whole);
    }

    #[test]
    fn inspect_writes_compact_json_for_every_reference_in_order() {
        let output = container_inspect(vec!["7b2".into(), "web".into()]).unwrap();
        let Output::Binary { data, .. } = output else {
            panic!("expected bytes");
        };
        assert_eq!(
            String::from_utf8(data).unwrap(),
            "[{\"id\":\"7b2e5a8f0c13d4f2\",\"name\":\"api\",\"image\":\"alpine:3.19\",\"state\":\"running\"},\
             {\"id\":\"3f1a9c2b7d4e0a11\",\"name\":\"web\",\"image\":\"alpine:3.19\",\"state\":\"running\"}]\n"
        );
    }

    #[test]
    fn an_ambiguous_prefix_is_a_domain_error() {
        let error = container_inspect(vec!["3f".into()]).unwrap_err();
        assert!(error.to_string().contains(
            "ambiguous reference: 3f matches 3f1a9c2b7d4e0a11, 3f8d4e6a1b90c7a3"
        ));
    }
}

